import re
f = 'glib/guri.c'
s = open(f).read()
# Add debug print at start of uri_decoder loop
old = """  decoded = g_malloc (length + 1);
  for (s = start, end = s + length, d = decoded; s < end; s++)
    {
      if (*s == '%')
        {"""
new = """  decoded = g_malloc (length + 1);
  fprintf(stderr, "uri_decoder: start=%.*s length=%zu\\n", (int)length, start, length);
  for (s = start, end = s + length, d = decoded; s < end; s++)
    {
      if (*s == '%')
        {
          fprintf(stderr, "  %% at offset %ld (end-offset %ld)\\n", (long)(s-start), (long)(end-start));"""
s = s.replace(old, new)
open(f,'w').write(s)
print("done")
EOF
